COMMENT ON TABLE public.wa_accounts IS 'DEPRECATED: replaced by shared official WhatsApp assistant configuration';
COMMENT ON TABLE public.wa_contacts IS 'DEPRECATED: contact monitoring replaced by verified phone linking';
COMMENT ON TABLE public.wa_messages IS 'DEPRECATED: replaced by wa_assistant_messages';
COMMENT ON TABLE public.wa_oauth_states IS 'DEPRECATED: per-user Meta OAuth abandoned';
CREATE TABLE public.wa_phone_links(user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE, phone text NOT NULL UNIQUE, linked_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.wa_phone_links TO authenticated; GRANT ALL ON public.wa_phone_links TO service_role;
ALTER TABLE public.wa_phone_links ENABLE ROW LEVEL SECURITY;
CREATE POLICY links_read ON public.wa_phone_links FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE POLICY links_delete ON public.wa_phone_links FOR DELETE TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.wa_link_codes(user_id uuid PRIMARY KEY REFERENCES public.profiles(user_id) ON DELETE CASCADE,code_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL);
GRANT ALL ON public.wa_link_codes TO service_role; ALTER TABLE public.wa_link_codes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.wa_assistant_messages(id text PRIMARY KEY,user_id uuid REFERENCES public.profiles(user_id) ON DELETE CASCADE,phone text NOT NULL,body text NOT NULL,sent_at timestamptz NOT NULL,state text NOT NULL DEFAULT 'pending',processing_error text,appointment_id text,clarification text,received_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.wa_assistant_messages TO authenticated; GRANT ALL ON public.wa_assistant_messages TO service_role; ALTER TABLE public.wa_assistant_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY assistant_read ON public.wa_assistant_messages FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE INDEX assistant_pending ON public.wa_assistant_messages(state,received_at);
CREATE TABLE public.wa_replies(inbound_id text PRIMARY KEY REFERENCES public.wa_assistant_messages(id) ON DELETE CASCADE,phone text NOT NULL,body text NOT NULL,state text NOT NULL DEFAULT 'pending',provider_id text UNIQUE,error text,sent_at timestamptz,delivered_at timestamptz,read_at timestamptz,failed_at timestamptz);
GRANT ALL ON public.wa_replies TO service_role; ALTER TABLE public.wa_replies ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.wa_redeem_code(p_hash text,p_phone text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid; BEGIN SELECT user_id INTO u FROM public.wa_link_codes WHERE code_hash=p_hash AND expires_at>now() FOR UPDATE; IF u IS NULL THEN RETURN NULL; END IF; IF EXISTS(SELECT 1 FROM public.wa_phone_links WHERE phone=p_phone AND user_id<>u) THEN RETURN NULL; END IF; INSERT INTO public.wa_phone_links(user_id,phone) VALUES(u,p_phone) ON CONFLICT(user_id) DO UPDATE SET phone=excluded.phone,linked_at=now(); DELETE FROM public.wa_link_codes WHERE user_id=u; RETURN u; END $$;
REVOKE ALL ON FUNCTION public.wa_redeem_code(text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.wa_redeem_code(text,text) TO service_role;